        text = text.replace(/"(?:\\.|[^"\\])*"|\bundefined\b|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/g,
            function (token, offset, original) {
                if (token.charAt(0) === '"') return token;
                if (token === 'undefined') {
                    return allowUndefined && /[\s,:\[]/.test(offset ? original.charAt(offset - 1) : ' ') &&
                        /[\s,}\]]/.test(original.charAt(offset + token.length) || ' ') ? 'null' : token;
                }
                return /^-?\d{16,}$/.test(token) ? JSON.stringify(token) : token;
            });
    }
    try { return JSON.parse(text); }
    catch (e) { throw new Error('番茄：响应不是预期的 JSON；可能需要登录或网页验证'); }
