function fqCommitSetting(src, host, key, value) {
    if (key === 'bubbleMode' && value === 'max') value='outline';
    if (key === 'chapterDiscussion') throw new Error('番茄：章末评论已移除，请重新打开设置');
    if (!Object.prototype.hasOwnProperty.call(FQ_SETTINGS_FIELDS,key) || FQ_SETTINGS_FIELDS[key].values.indexOf(value) < 0) throw new Error('番茄：无效的设置选项');
