    if (old === value && (key !== 'exploreMode' || (values.exploreLayoutRevision === FQ_EXPLORE_LAYOUT_REVISION && values.exploreMode === value))) return false;
    // Reload source state for each event and write only the changed field.
    // Other controls in a native result Map may be stale or from another page.
    values[key] = value;
    if (key === 'exploreMode') values.exploreLayoutRevision = FQ_EXPLORE_LAYOUT_REVISION;
    src.putVariable(JSON.stringify(values));
    if (key === 'exploreMode') {
        var message = '已保存；返回发现页后长按书源名刷新';
        try { fqClearDiscoverySettings(src); } catch (error) { message = '布局已保存，请返回发现页刷新'; }
        fqSettingsToast(host,message);
