    if (key === 'bubbleMode' && (raw === null || typeof raw === 'undefined')) {
        raw = form && typeof form.get === 'function' ? form.get('fqV6Bubble') : form && form.fqV6Bubble;
        if (fqString(raw) === 'Max 内置') raw='通用线框';
