var FQ_ACCOUNT_SITE = FQ_ORIGIN+'/';
var FQ_ACCOUNT_DOMAIN = FQ_ORIGIN.slice(8);
var FQ_ACCOUNT_INFO = FQ_ORIGIN+'/api/user/info/v2';

function fqAccountValues(src) {
    var raw = src && typeof src.getVariable === 'function' ? src.getVariable() : '';
    var values = raw == null || !String(raw).trim() ? {} : fqParseJson(String(raw),false);
    if (!values || typeof values !== 'object' || Array.isArray(values)) throw new Error('账号设置无法读取');
    return values;
