function fqAccountDisplay(status, name) {
    name = typeof name === 'string' ? name.replace(/[\u0000-\u001f\u007f]/g,'').trim().slice(0,80) : '';
    if (status !== 'signed-in' && status !== 'signed-out') status = 'unknown';
    if (status === 'signed-in' && !name) status = 'unknown';
    if (status !== 'signed-in') name = '';
    return {status:status,name:name,label:status === 'signed-in' ? '上次已验证 · ' + name : status === 'signed-out' ? '未登录' : '状态待检查'};
}

function fqAccountState(src) {
    try { var account = fqAccountValues(src).account || {}; return fqAccountDisplay(account.status,account.name); }
    catch (ignore) { return fqAccountDisplay('unknown',''); }
}

function fqAccountFinish(src, host, status, name, message) {
    var state = fqAccountDisplay(status,name);
    try {
        var values = fqAccountValues(src);
        values.account = {status:state.status,name:state.name};
        src.putVariable(JSON.stringify(values));
    } catch (ignore) { message += '；本地状态未保存，请重新打开设置'; }
    fqSettingsToast(host,message); fqRebuildLogin(host);
    return state;
}

function fqAccountSession(cookieHost) {
    if (!cookieHost || typeof cookieHost.getKey !== 'function') throw new Error('客户端未提供站点会话接口');
    var raw = cookieHost.getKey(FQ_ACCOUNT_DOMAIN,'sessionid');
    var value = raw == null ? '' : String(raw).trim();
    if (!value || value === 'null' || value === 'undefined') return '';
    // A session cookie is an opaque value, never a header or an executable rule.
    if (!/^[A-Za-z0-9._~%+=\/-]{1,2048}$/.test(value)) throw new Error('站点会话格式异常');
    return value;
}


function fqAccountCookieMap(text) {
    var out={},parts=String(text||'').split(';');
    for(var i=0;i<parts.length;i++) {
        var part=parts[i].trim(),at=part.indexOf('=');
        if(at<1)continue;
        var key=part.slice(0,at).trim(),value=part.slice(at+1).trim();
        if(!/^[A-Za-z0-9_.-]+$/.test(key)||/[\x00-\x1f\x7f]/.test(value))throw new Error('官网会话格式异常');
        out[key]=value;
    }
    return out;
}

function fqAccountCookieText(cookieHost) {
    if(!cookieHost||typeof cookieHost.getCookie!=='function') {
        var session=fqAccountSession(cookieHost);
        return session?'sessionid='+session:'';
    }
    var raw=String(cookieHost.getCookie(FQ_ACCOUNT_SITE)||'');
    if(/[\r\n\x00]/.test(raw)||raw.length>32768)throw new Error('官网会话格式异常');
    var values=fqAccountCookieMap(raw),parts=[];
    for(var key in values)if(Object.prototype.hasOwnProperty.call(values,key))parts.push(key+'='+values[key]);
    return parts.join('; ');
}

function fqAccountAuthSignature(text) {
    var values=fqAccountCookieMap(text),keys=['sessionid','sessionid_ss','sid_tt','sid_guard'],parts=[];
    for(var i=0;i<keys.length;i++)if(values[keys[i]])parts.push(keys[i]+'='+values[keys[i]]);
    return parts.join('; ');
}

function fqAccountCache(store) {
    return store||(typeof cache==='undefined'?null:cache);
}

function fqAccountSync(cookieHost,store,required) {
    if(!cookieHost||typeof cookieHost.getCookie!=='function'||typeof cookieHost.setCookie!=='function') {
        if(required)throw new Error('客户端无法同步官网会话');
        return false;
    }
    store=fqAccountCache(store);
