            cookieHost.removeCookie(FQ_ACCOUNT_SITE);changed=true;
            if(fqAccountCookieText(cookieHost))throw new Error('旧会话未清除');
            cookieHost.captureFromWebView(FQ_ACCOUNT_SITE,FQ_ACCOUNT_SITE);
            if(!fqAccountAuthSignature(fqAccountCookieText(cookieHost)))throw new Error('网页尚未提供登录会话');
            return true;
        } catch(ignore) {
            if(changed)try {
                cookieHost.removeCookie(FQ_ACCOUNT_SITE);
                if(prior)cookieHost.setCookie(FQ_ACCOUNT_SITE,prior);
                if(fqAccountCookieText(cookieHost)!==prior)throw new Error('恢复失败');
            }catch(restoreError){throw new Error('官网会话同步失败，原有记录未能恢复，请重新网页登录');}
