            // store protects it, but cannot prove it is the browser's current
            // account. A status check must not validate that old account next.
            throw new Error('未确认网页登录会话，请完成网页登录后重试');
        }
    }
    var webText;
    try {
        webText=String(Packages.android.webkit.CookieManager.getInstance().getCookie(FQ_ACCOUNT_SITE)||'');
    }catch(ignore){if(required)throw new Error('无法读取网页登录会话，请稍后检查登录状态');return false;}
    if(/[\r\n\x00]/.test(webText)||!fqAccountAuthSignature(webText)) {
        if(required)throw new Error('网页尚未提供登录会话，请完成网页登录后重试');
