        if(root&&String(root.code)==='-1'&&/请先登录|未登录|登录已失效/.test(String(root.message||'')))return fqAccountFinish(src,host,'signed-out','','登录已失效，请重新登录');
        if(!root||String(root.code)!=='0'||!data||Array.isArray(data))throw new Error('账号信息暂不可用');
