        return fqAccountFinish(src,host,'signed-in',state.name,'已验证番茄账号：'+state.name);
    }catch(ignore){return fqAccountFinish(src,host,'unknown','','暂时无法检查账号，可能是网络或官网验证，请稍后重试');}
}

function fqAccountCheck(src,host,cookieHost,store) {
    try{
        // NG's browser is shared while the source cookie jar is scoped. An
        // explicit local logout must not be undone by this refresh action.
        if(cookieHost&&typeof cookieHost.captureFromWebView==='function'&&fqAccountValues(src).accountWebSyncSuppressed===true) {
            return fqAccountFinish(src,host,'signed-out','','本源登录已清除，请点“网页登录”重新启用');
        }
        fqAccountSync(cookieHost,store,false);
    }
    catch(ignore){return fqAccountFinish(src,host,'unknown','','官网会话同步失败，请重新检查登录状态或网页登录');}
    return fqAccountVerify(src,host,cookieHost);
}

function fqAccountSuppressBrowserSync(src,suppress) {
    var values=fqAccountValues(src);
    if(suppress)values.accountWebSyncSuppressed=true;
    else delete values.accountWebSyncSuppressed;
    src.putVariable(JSON.stringify(values));
}

function fqAccountLogin(src,host,cookieHost,store) {
    try {
        if(!host||typeof host.startBrowserAwait!=='function')throw new Error('客户端未提供登录窗口');
        // All audited branches offer this overload. Returning the current DOM
        // avoids a pre-sync HTTP refetch with a stale app-side cookie store.
        var loginUrl=FQ_ORIGIN+'/main/writer/login?_login_data='+encodeURIComponent(JSON.stringify({needRedirect:true,redirectURLs:{login:FQ_ACCOUNT_SITE}}));
        host.startBrowserAwait(loginUrl,'番茄网页登录',false);
    }catch(ignore){return fqAccountFinish(src,host,'unknown','','未完成网页登录，账号状态尚未验证');}
    try{
        fqAccountSync(cookieHost,store,true);
        // Only an explicitly completed login with a captured browser session
        // may undo local logout. Cancellation keeps suppression in place.
        fqAccountSuppressBrowserSync(src,false);
    }
    catch(ignore){return fqAccountFinish(src,host,'unknown','','官网会话同步失败，请重新检查登录状态或网页登录');}
    return fqAccountVerify(src,host,cookieHost);
}

function fqAccountClear(src, host, cookieHost) {
    var browserCleared=true;
    try {
        if (!cookieHost || typeof cookieHost.removeCookie !== 'function') throw new Error('客户端未提供清理接口');
        cookieHost.removeCookie(FQ_ACCOUNT_DOMAIN);
        if (fqAccountAuthSignature(fqAccountCookieText(cookieHost))) throw new Error('本机仍有站点会话');
        if(typeof cookieHost.captureFromWebView==='function') {
            // NG removeCookie clears only the scoped app jar. Its public
            // applyToWebView removes fixed-target WebView cookies before
            // writing that (now empty) jar, and flushes CookieManager.
            // Suppression also protects against older bridges and asynchronous
            // or failed browser cleanup. No unrelated domains are touched.
            fqAccountSuppressBrowserSync(src,true);
            browserCleared=false;
            if(typeof cookieHost.applyToWebView==='function') {
                try {
                    cookieHost.applyToWebView(FQ_ACCOUNT_SITE,FQ_ACCOUNT_SITE);
                    cookieHost.captureFromWebView(FQ_ACCOUNT_SITE,FQ_ACCOUNT_SITE);
                    browserCleared=!fqAccountAuthSignature(fqAccountCookieText(cookieHost));
                }catch(ignore){}
                // A failed purge must not leave the verification capture's
                // still-active browser cookie back in this source's app jar.
                cookieHost.removeCookie(FQ_ACCOUNT_DOMAIN);
                if(fqAccountAuthSignature(fqAccountCookieText(cookieHost)))throw new Error('本源会话未清除');
            }
        } else {
            fqAccountSuppressBrowserSync(src,false);
        }
    } catch (ignore) { return fqAccountFinish(src,host,'unknown','','本机登录未能完全清除，请重新打开网页登录检查'); }
    return fqAccountFinish(src,host,'signed-out','',browserCleared?'已清除本源可见的本机网页登录':'已清除本源登录；网页会话仍可能保留，检查状态不会重新导入，需点“网页登录”才能重新启用');
}

/* Independent local policy. No proxy, entitlement bypass or paid fallback. */
var FQ_QUOTA_KEY='fq-paragraph-only-v1:daily-chapters';
var FQ_QUOTA_LOCK='fq-paragraph-only-v1:daily-chapters:monitor';
var FQ_QUOTA_LIMIT=500;
function fqPolicyLock(host,action) {
    var done=false,value,error=null;
    function run(){try{value=action();}catch(e){error=e;}finally{done=true;}}
    if(host && typeof host.lock==='function') {
        // Max lock returns void. Capture the callback result and failure; a
        // skipped/timed-out callback must never return a placeholder URL.
        host.lock(FQ_QUOTA_LOCK,run,30000);
    } else {
        // Public Java API, available since Android 7/API 24. Properties inherits
        // Hashtable's synchronized compute: every script scope uses the same
        // JVM monitor. Preserve the original value (including null); no secret,
        // counter or Java object is inserted into system properties. The action
        // MUST stay short and contain no HTTP, browser operation or callback UI.
        try {
            var properties=Packages.java.lang.System.getProperties();
            properties.compute(FQ_QUOTA_LOCK,function(key,previous){run();return previous;});
        } catch(ignore) {
            if(!done)throw new Error('番茄：当前阅读器不支持安全额度锁，请升级阅读器或 Android 系统');
        }
    }
    if(!done)throw new Error('番茄：额度锁等待失败，已停止正文请求');
    if(error)throw error;
    return value;
}
function fqPolicyDay(now) {return Math.floor((Number(now)+28800000)/86400000);}
function fqQuotaState(store,now) {
    if(!store||typeof store.get!=='function'||typeof store.put!=='function')throw new Error('番茄：当前阅读器不支持持久额度，已停止正文请求');
    var day=fqPolicyDay(now),raw=store.get(FQ_QUOTA_KEY),value;
    if(raw==null||String(raw)==='')return {schema:1,day:day,count:0};
    try{value=JSON.parse(String(raw));}catch(ignore){throw new Error('番茄：额度记录损坏，已停止正文请求');}
    if(!value||value.schema!==1||typeof value.day!=='number'||Math.floor(value.day)!==value.day||typeof value.count!=='number'||Math.floor(value.count)!==value.count||value.count<0||value.count>FQ_QUOTA_LIMIT)throw new Error('番茄：额度记录异常，已停止正文请求');
    if(day<value.day)throw new Error('番茄：系统日期早于额度记录，请校准日期后重试');
    return day===value.day?value:{schema:1,day:day,count:0};
}
// Keep the legacy route's fourth field readable, without using it as a gate.
function fqPolicyPaid(data) {
    function yes(v){return v===true||v==='true'||v===1||v==='1';}
    if(yes(data.isPaidPublication)||yes(data.isPaidStory)||Number(data.needPay)>0)return 1;
    return data.needPay===0||data.needPay==='0'?0:2;
}
function fqPolicyPermitKey(bid,cid){return 'fq-paragraph-only-v1:permit:'+bid+':'+cid;}
function fqBeforeChapter(route,src,host,store,cookies) {
    var a=route.data;
    // The authoritative count is read again inside the atomic section.
    if(fqQuotaState(store,Date.now()).count>=FQ_QUOTA_LIMIT)throw new Error('番茄：今日正文请求已达 500 章，请北京时间明日再读；已有离线缓存可继续阅读');
    // Website login is optional at every chapter. Reuse an existing session,
    // but never require a local account check before requesting the page.
    var cookieText='';
    try{if(cookies)cookieText=fqAccountCookieText(cookies);}catch(ignore){}
    var headers=host && (host.headerMap || (typeof host.getHeaderMap==='function'?host.getHeaderMap():null));
    return fqPolicyLock(host,function(){
        var now=Date.now(),quota=fqQuotaState(store,now);
        if(quota.count>=FQ_QUOTA_LIMIT)throw new Error('番茄：今日正文请求已达 500 章，请北京时间明日再读；已有离线缓存可继续阅读');
        // AnalyzeUrl's headerMap is bound to this individual request only.
        if(cookieText&&headers&&typeof headers.put==='function')headers.put('Cookie',cookieText);
        quota.count++;
        store.put(FQ_QUOTA_KEY,JSON.stringify(quota),0);
        var stored=fqQuotaState(store,now);
        if(stored.count!==quota.count)throw new Error('番茄：额度保存失败，已停止正文请求');
        store.put(fqPolicyPermitKey(a[0],a[1]),JSON.stringify({book:a[0],chapter:a[1],order:a[2],at:now}),3600);
        return FQ_ORIGIN+'/reader/'+a[1];
    });
}
function fqPolicyContent(input,url,host,src,store,cookies) {
    var route=fqRouteInfo(url),a=route.data;
    if(route.kind!=='chapter')throw new Error('番茄：正文请求缺少章节限制信息');
    var permit=null;try{permit=JSON.parse(String(store.get(fqPolicyPermitKey(a[0],a[1]))||'null'));}catch(ignore){}
    if(!permit||permit.book!==a[0]||permit.chapter!==a[1]||permit.order!==a[2]||Date.now()<permit.at||Date.now()-permit.at>3600000)throw new Error('番茄：正文请求授权已失效，请刷新本章');
    var data=fqState(input).reader;data=data&&data.chapterData;
    if(!data||String(data.bookId)!==a[0]||String(data.itemId)!==a[1]||Number(data.realChapterOrder)!==a[2])throw new Error('番茄：正文书章或序号与目录不一致，已停止读取');
    // One bounded public read only when the official page supplies a preview.
    // The logical chapter reservation covers both steps, never a second book.
    // Keep transport outside the quota monitor and preserve the original IDs.
    if(fqIsPreview(data))return fqReviewedChapter(fqPublicChapter(data,host),host,src,store);
    return fqReviewedContent(input,FQ_ORIGIN+'/reader/'+a[1],host,src,store);
}

/* Independently implemented from captured public responses. No device pool,
 * borrowed session, executable remote library or third-party content proxy. */
function fqIsPreview(data) {
    var v=data&&data.isChapterLock;
    return v===true||v==='true'||v===1||v==='1';
}
function fqPublicChapter(data,host) {
