id=\"clearSearch\" aria-label=\"清空分类搜索\" hidden><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"m5 5 10 10M15 5 5 15\"/></svg></button></div>\n<div id=\"categoryGroups\" class=\"groups\" aria-label=\"分类分组\"></div>\n<div id=\"filterPanel\" class=\"filters\" aria-label=\"书库筛选\" hidden><label class=\"filter\"><span class=\"filter-label\">状态</span><select id=\"creationStatus\" aria-label=\"作品状态\"></select></label><label class=\"filter\"><span class=\"filter-label\">字数</span><select id=\"wordCount\" aria-label=\"作品字数\"></select></label><label class=\"filter\"><span class=\"filter-label\">排序</span><select id=\"sort\" aria-label=\"排序方式\"></select></label><div class=\"filter-actions\"><button id=\"clearFilters\" class=\"reset-filters\" hidden>重置筛选</button></div></div>\n<div id=\"categories\" class=\"categories\"></div><button id=\"moreCategories\" class=\"more\" hidden></button>\n</div>\n</section>\n<section id=\"ranking\" role=\"tabpanel\" aria-labelledby=\"tabRank\" hidden><div class=\"rank-top\"><div id=\"rankChannels\" class=\"segments\" aria-label=\"榜单频道\"></div><div id=\"rankTypes\" class=\"rank-types\" aria-label=\"榜单类型\"></div></div><div class=\"rank-section\"><h2 class=\"rank-heading sr-only\" id=\"rankHeading\">阅读榜 · 分类</h2><div id=\"rankCategories\" class=\"categories rank-grid\"></div></div></section>\n</main>\n<script id=\"discovery-data\" type=\"application/json\">\"__DISCOVERY_DATA__\"</script>\n<script>\n(function(){\n 'use strict';\n var data=JSON.parse(document.getElementById('discovery-data').textContent),state={mode:'library',gender:-1,group:'主分类',search:'',expanded:false,creationStatus:-1,wordCount:-1,sort:0,rankGender:1,rankType:2};\n function el(id){return document.getElementById(id);}function node(tag,text,cls){var n=document.createElement(tag);n.textContent=text==null?'':String(text);if(cls)n.className=cls;return n;}\n function textOf(rows,id){for(var i=0;i<rows.length;i++)if(Number(rows[i].id)===Number(id))return rows[i].name;return '';}\n function button(text,id,selected,cls,click){var b=node('button',text,cls);b.type='button';if(selected!==null)b.setAttribute('aria-pressed',String(selected));b.dataset.value=String(id);b.onclick=function(){var focused=document.activeElement===b,parentId=b.parentElement&&b.parentElement.id,value=b.dataset.value;click();if(focused&&parentId){var parent=document.getElementById(parentId);if(parent){var choices=parent.querySelectorAll('button');for(var i=0;i<choices.length;i++)if(choices[i].dataset.value===value){choices[i].focus({preventScroll:true});break;}}}};return b;}\n function channel(){return data.channels.filter(function(x){return Number(x.id)===state.gender;})[0]||data.channels[0];}\n function clearError(){el('error').hidden=true;el('error').textContent='';}\n function openList(kind,id){clearError();var url,title;if(kind==='library'){url=\"__FQ_SITE__\"+'/api/author/library/book_list/v0/?page_count=18&page_index={{page-1}}&gender='+state.gender+'&category_id='+id+'&book_type=-1&creation_status='+state.creationStatus+'&word_count='+state.wordCount+'&sort='+state.sort;title=channel().name+' · '+(textOf(data.categories,id)||'全部分类');}else{url=\"__FQ_SITE__\"+'/api/rank/category/list?app_id=2503&rank_list_type=3&offset={{(page-1)*10}}&limit=10&category_id='+id+'&rank_version=&gender='+state.rankGender+'&rankMold='+state.rankType;title=(state.rankGender===1?'男生':'女生')+' · '+textOf(data.rankings.types,state.rankType)+' · '+textOf(rankRows(),id);}try{if(typeof java==='undefined'||typeof java.open!=='function')throw new Error('请在阅读 Max 中打开，或切换为经典分类列表。');java.open('explore',url,title);}catch(error){el('error').textContent=String(error.message||error);el('error').hidden=false;}}\n function renderChannels(){var target=el('channels');target.textContent='';data.channels.forEach(function(c){target.appendChild(button(c.name,c.id,Number(c.id)===state.gender,'segment',function(){state.gender=Number(c.id);state.expanded=false;clearError();renderChannels();renderCategories();}));});}\n function availableCategories(){var allowed=channel().categoryIds||[];return data.categories.filter(function(x){return allowed.indexOf(Number(x.id))>=0;});}\n function renderGroups(){var target=el('categoryGroups');target.textContent='';data.groups.concat(['全部']).forEach(function(g){target.appendChild(button(g,g,g===state.group,'',function(){state.group=g;state.expanded=false;state.search='';el('categorySearch').value='';renderCategories();}));});}\n function card(name,id,all){var b=button('',id,null,'category'+(all?' category-all':''),function(){openList('library',Number(id));});b.setAttribute('aria-label',name);b.appendChild(node('strong',name));return b;}\n function renderCategories(){renderGroups();var rows=availableCategories(),q=state.search.trim().toLowerCase();if(q)rows=rows.filter(function(c){return String(c.name).toLowerCase().indexOf(q)>=0;});else if(state.group!=='全部')rows=rows.filter(function(c){return c.group===state.group;});if(!q&&state.group==='主分类'){var order=[261,258,1140,273,8,539,748,253,749,79,718],original=rows.slice();rows.sort(function(a,b){var ai=order.indexOf(Number(a.id)),bi=order.indexOf(Number(b.id));return(ai<0?order.length+original.indexOf(a):ai)-(bi<0?order.length+original.indexOf(b):bi);});}var target=el('categories');target.textContent='';el('categoryCount').textContent=rows.length+' 类';target.appendChild(card('全部书籍',-1,true));var limit=state.expanded||q?rows.length:11;rows.slice(0,limit).forEach(function(c){target.appendChild(card(c.name,c.id,false));});if(!rows.length)target.appendChild(node('div','没有找到，试试其他分类名称。','empty'));el('clearSearch').hidden=!state.search;el('moreCategories').hidden=!!q||rows.length<=11;el('moreCategories').textContent=state.expanded?'收起分类':'展开其余 '+(rows.length-11)+' 项';updateFilterState();}\n function updateFilterState(){var count=(state.creationStatus!==-1?1:0)+(state.wordCount!==-1?1:0)+(state.sort!==0?1:0);el('clearFilters').hidden=count===0;el('filterLabel').textContent=count?'筛选 · '+count:'筛选';