function fqClassicItems(state) {
    var d=FQ_DISCOVERY_DATA;
    if(state.view==='rank') return state.rankGender===0?d.rankings.female:d.rankings.male;
    var channel=d.channels[0];
    for(var i=0;i<d.channels.length;i++) if(d.channels[i].id===state.libraryGender) channel=d.channels[i];
    return d.categories.filter(function(x){return x.group===state.group && channel.categoryIds.indexOf(x.id)>=0;});
}

function fqClassicPageInfo(state) {
    var items=fqClassicItems(state), size=24, count=Math.max(1,Math.ceil(items.length/size));
    return {items:items,size:size,count:count,page:Math.min(state.page,count-1)};
}

function fqClassicLabel(key,value) {
    var options=fqClassicOptions(key);
    for(var i=0;i<options.length;i++) if(options[i].id===value) return options[i].name;
    return '';
}

function fqClassicSyncForm(src,form,keys) {
    if(!form) return;
    var state=fqClassicState(src);
    for(var i=0;i<keys.length;i++) {
        var key=keys[i];
        var name=FQ_CLASSIC_FIELDS[key].title, value=fqClassicLabel(key,state[key]);
        try { if(typeof form.put==='function') form.put(name,value); else form[name]=value; } catch(ignore) {}
    }
}

function fqClassicRefresh(src,host,form) {
    try { if(src && typeof src.refreshExplore==='function') src.refreshExplore(); } catch(ignore) {}
    if(host && typeof host.refreshExplore==='function') {host.refreshExplore();return;}
    fqSettingsToast(host,'已保存，请返回发现页刷新');
}

function fqClassicPatch(src,host,form,patch,syncKeys) {
    var values=fqStoredSettings(src), current=values.classicDiscovery;
    if(!current || typeof current!=='object' || Array.isArray(current)) current={};
    for(var key in patch) if(Object.prototype.hasOwnProperty.call(patch,key)) current[key]=patch[key];
    values.classicDiscovery=current;
    src.putVariable(JSON.stringify(values));
    if(syncKeys && syncKeys.length) fqClassicSyncForm(src,form,syncKeys);
    // Commit native control state in the same user action. Reading a menu
    // still never writes the map and cannot overwrite a pending selection.
    if(form && typeof form.saveNow==='function') form.saveNow();
    fqClassicRefresh(src,host,form);
}

function fqClassicSelect(src,host,form,key) {
    if(!Object.prototype.hasOwnProperty.call(FQ_CLASSIC_FIELDS,key)) throw new Error('番茄：无效的发现选项');
    var name=FQ_CLASSIC_FIELDS[key].title;
    var raw=form && typeof form.get==='function'?form.get(name):form && form[name];
    var options=fqClassicOptions(key), found=false, value;
    for(var i=0;i<options.length;i++) if(options[i].name===fqString(raw)) {found=true;value=options[i].id;break;}
    if(!found) throw new Error('番茄：发现选项已变化，请刷新发现页');
    var state=fqClassicState(src);
    if(state[key]===value) return;
    var patch={page:0}, sync=[];patch[key]=value;
    // The four visible filters use Fanqie's documented library parameters.
    // A filter selection opens that library, instead of silently doing nothing
    // while the user happens to be looking at a ranking.
    if(['group','creationStatus','wordCount','sort'].indexOf(key)>=0 && state.view!=='library') {patch.view='library';sync.push('view');}
    if(key==='libraryGender') {
        var nextGroup=fqClassicCompatibleGroup(value,state.group);
        if(nextGroup!==state.group) {patch.group=nextGroup;sync.push('group');}
    }
    if(key==='group') {
        patch.group=fqClassicCompatibleGroup(state.libraryGender,value);
        if(patch.group!==value) sync.push('group');
    }
    fqClassicPatch(src,host,form,patch,sync);
}

function fqClassicToggleFilters(src,host,form) {
    fqClassicPatch(src,host,form,{filtersExpanded:!fqClassicState(src).filtersExpanded});
}

function fqClassicResetFilters(src,host,form) {
    fqClassicPatch(src,host,form,{creationStatus:-1,wordCount:-1,sort:0,page:0},['creationStatus','wordCount','sort']);
}

function fqClassicMovePage(src,host,form,direction) {
    var state=fqClassicState(src), page=fqClassicPageInfo(state);
    var next=Math.max(0,Math.min(page.count-1,page.page+(Number(direction)<0?-1:1)));
    if(next!==page.page) fqClassicPatch(src,host,form,{page:next});
}

function fqClassicFormGet(form,key) {
    return form && typeof form.get==='function'?form.get(key):form && form[key];
}

function fqClassicSearch(src,host,form) {
    var key=fqString(fqClassicFormGet(form,FQ_CLASSIC_KEYWORD)).trim();
    if(!key) {fqSettingsToast(host,'请先输入书名或作者');return false;}
    if(!host || typeof host.searchBook!=='function') throw new Error('番茄：当前阅读器未提供发现页搜索，请使用顶部搜索');
    var name=fqString(src.bookSourceName);
    if(!name && typeof src.getBookSourceName==='function') name=fqString(src.getBookSourceName());
    host.searchBook(key,name+'::'+fqString(src.getKey()));
    return true;
}

function fqClassicResetSearch(src,host,form) {
    if(form) {
        if(typeof form.put==='function') form.put(FQ_CLASSIC_KEYWORD,'');else form[FQ_CLASSIC_KEYWORD]='';
        if(typeof form.saveNow==='function') form.saveNow();
    }
    fqClassicRefresh(src,host,form);
}

function fqClassicResetDiscovery(src,host,form) {
    fqClassicPatch(src,host,form,{view:'rank',libraryGender:1,rankGender:1,group:FQ_DISCOVERY_DATA.groups[0],creationStatus:-1,wordCount:-1,sort:0,rankMold:2,page:0,filtersExpanded:true},Object.keys(FQ_CLASSIC_FIELDS));
}

function fqClassicLogin(src,host,form) {
    if(!host || typeof host.open!=='function') throw new Error('番茄：当前阅读器未提供此入口，请从书源菜单打开登录');
    var values=fqStoredSettings(src);values.settingsMenu='account';src.putVariable(JSON.stringify(values));
    host.open('login','http',null);
}

function fqClassicRankKind(src,host,form,kind) {
    if(kind!==1 && kind!==2) throw new Error('番茄：无效榜单类型');
    if(fqClassicState(src).rankMold!==kind) fqClassicPatch(src,host,form,{rankMold:kind,page:0},['rankMold']);
}

function fqClassicDiscovery(src,host,form) {
    var state=fqClassicState(src), page=fqClassicPageInfo(state), rows=[], i;
    // Do not write InfoMap while rendering: native controls write the event
    // before asynchronously running its action. An overlapping old render
    // must not replace that pending event with the previous source value.
    function style(width,wrap,start) {return {layout_flexBasisPercent:width,layout_flexGrow:1};}
    function button(title,action,width,wrap) {var st=style(width==null?0.4:width,wrap,false);st.layout_alignSelf='baseline';rows.push({title:title,type:'button',action:action,style:st});}
    function heading(title) {rows.push({title:title,type:'button',action:null,style:style(1,true,true)});}
    function link(title,url,width,wrap) {rows.push({title:title,type:'url',url:url,style:style(width||0.4,wrap,false)});}
    function action(name,extra) {return name+'(source,java,typeof infoMap === "undefined" ? null : infoMap'+(extra?','+extra:'')+')';}
    function select(key,width,wrap) {
        var field=FQ_CLASSIC_FIELDS[key];
        rows.push({title:field.title,viewName:"'"+field.label+"'",type:'select',chars:fqClassicOptions(key).map(function(x){return x.name;}),default:fqClassicLabel(key,state[key]),
            action:action('fqClassicSelect',JSON.stringify(key)),style:style(width||1,wrap,true)});
    }
    function library(category) {
        return fqLibraryUrl({gender:state.libraryGender,categoryId:category,creationStatus:state.creationStatus,wordCount:state.wordCount,sort:state.sort},1).replace('page_index=0&','page_index={{page-1}}&');
    }
    function rank(category) {return fqRankUrl({gender:state.rankGender,rankMold:state.rankMold,categoryId:category},1).replace('offset=0&','offset={{(page-1)*10}}&');}

    rows.push({title:FQ_CLASSIC_KEYWORD,type:'text',style:{layout_flexGrow:1,layout_flexBasisPercent:0.6}});
    button('📤搜索',action('fqClassicSearch'),-1);
    select('group',0.4);select('creationStatus',0.4);
    select('wordCount',0.4);select('sort',0.4);
    button('🔑登录',action('fqClassicLogin'),0.4);button('⏰刷新发现页',action('fqClassicRefresh'),0.4);
    button('♻重置搜索',action('fqClassicResetSearch'),0.45);button('🧹重置发现',action('fqClassicResetDiscovery'),0.45);
    select('view',1);
    select(state.view==='rank'?'rankGender':'libraryGender',1);
    if(state.view==='rank') {
        button((state.rankMold===2?'✓ ':'')+'阅读榜',action('fqClassicRankKind','2'),0.4);
        button((state.rankMold===1?'✓ ':'')+'新书榜',action('fqClassicRankKind','1'),0.4);
    } else {
        link('查看全部作品',library(-1),1,true);
        heading(state.group+' · '+page.items.length+' 类'+(page.count>1?' · '+(page.page+1)+'/'+page.count:''));
    }
    if(!page.items.length) heading('此频道暂无该组分类，请切换分类或频道');
    var end=Math.min(page.items.length,(page.page+1)*page.size);
    for(i=page.page*page.size;i<end;i++) link(page.items[i].name+(state.view==='rank'?'榜':''),state.view==='rank'?rank(page.items[i].id):library(page.items[i].id),0.4,(i-page.page*page.size)%2===0);
    if(page.count>1) {
        button(page.page>0?'上一页':'已是首页',page.page>0?action('fqClassicMovePage','-1'):null,0.4,true);
        button(page.page<page.count-1?'下一页':'已是末页',page.page<page.count-1?action('fqClassicMovePage','1'):null,0.4,false);
    }
    return rows;
}

function fqDiscovery(src,host,form) {
    if(fqSettings(src).exploreMode!=='rich') return JSON.stringify(fqClassicDiscovery(src,host,form));
    return '<useweb>' + FQ_DISCOVERY_HTML.replace('"__DISCOVERY_DATA__"',function(){return fqSafeConfig(FQ_DISCOVERY_DATA);})
        .split('"__FQ_SITE__"').join(JSON.stringify(FQ_ORIGIN))
        .replace('"__FQ_THEME__"',function(){return fqSafeConfig(fqTheme(host));})
        .replace('/*__FQ_THEME_SCRIPT__*/',function(){return FQ_THEME_JS;}) + '</useweb>';
}

