dary:'--muted',primary:'--primary',surface:'--surface',soft:'--soft',selectedBackground:'--selected',divider:'--line'};Object.keys(keys).forEach(function(k){if(theme[k])document.documentElement.style.setProperty(keys[k],theme[k]);});document.documentElement.style.setProperty('color-scheme',theme.dark?'dark':'light');}\n function theme(){try{if(typeof fqTheme==='function'&&typeof java!=='undefined')apply(fqTheme(java));}catch(ignore){}}\n apply(config.theme);theme();window.addEventListener('pageshow',theme);document.addEventListener('visibilitychange',function(){if(!document.hidden)theme();});\n [book.status,book.words,book.chapters?'共'+book.chapters+'章':'',book.readers].forEach(function(text){if(text){var item=document.createElement('span');item.textContent=text;el('summary').appendChild(item);}});\n el('summary').hidden=!el('summary').children.length;\n book.tags.forEach(function(text){var item=document.createElement('span');item.className='tag';item.textContent=text;el('tags').appendChild(item);});el('tags').hidden=!book.tags.length;\n el('updated').textContent=book.updated?'更新于 '+book.updated:'';el('updated').hidden=!book.updated;\n el('information').hidden=!el('summary').children.length&&!book.tags.length&&!book.updated;\n el('abstract').textContent=book.abstract||'暂无简介';\n})();\n</script></body></html>\n";

function fqInfoNumber(value, unit) {
    var n = Number(value);
    if (!isFinite(n) || n <= 0) return '';
    return (n >= 10000 ? (Math.round(n / 1000) / 10).toFixed(1).replace(/\.0$/, '') + '万' : String(Math.floor(n))) + unit;
}

function fqInfoDate(value) {
    var n = Number(value);
    if (!isFinite(n) || n <= 0) return '';
    // Platform timestamps are seconds. Display the site's China time independently
    // of the testing computer's local time zone.
    var d = new Date(n * 1000 + 8 * 3600000);
    if (isNaN(d.getTime())) return '';
    function pad(x) { return ('0' + x).slice(-2); }
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes());
}

function fqInfoModel(input, src, cacheHost) {
    var b = fqParseJson(input, false), tags = [], categories;
    try { categories = typeof b.categoryV2 === 'string' ? fqParseJson(b.categoryV2, false) : b.categoryV2; } catch (ignore) {}
    if (Array.isArray(categories)) for (var i = 0; i < categories.length; i++) {
        var name = fqString(categories[i] && (categories[i].Name || categories[i].name)).trim();
        if (name && tags.indexOf(name) < 0) tags.push(name);
    }
    if (!tags.length && b.category) tags = fqString(b.category).split(' · ');
    var status = String(b.creationStatus) === '0' ? '已完结' : String(b.creationStatus) === '1' ? '连载中' : '';
    return {bookId:fqId(b.bookId),bookName:fqString(b.bookName),status:status,chapters:fqCachedTocSize(b.bookId,src,cacheHost),
        words:fqInfoNumber(b.wordNumber, '字'),readers:fqInfoNumber(b.readCount, '人在读'),
        updated:fqInfoDate(b.lastPublishTime),tags:tags,abstract:fqString(b.abstract)};
}

function fqBookIntro(input, host, src, cacheHost) {
    var config = {book:fqInfoModel(input,src,cacheHost),theme:fqTheme(host)};
    // AnalyzeRule decodes HTML entities once before handing <useweb> to WebView.
    // Keep remote prose in JSON and escape ampersands as well as '<' so neither
    // this layer nor the browser can turn prose into executable markup.
    var encoded = fqSafeConfig(config).replace(/&/g, '\\u0026');
    return '<useweb>' + FQ_INTRO_HTML.replace('"__FQ_INTRO__"', function () { return encoded; }) + '</useweb>';
}

/* Official paragraph-share protocol; IDs are kept as strings throughout. */
function fqParagraphText(html) {
    var named = {amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' '};
    return fqString(html).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]*>/g, '')
        .replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi, function (all, code) {
            if (code.charAt(0) !== '#') return named[code.toLowerCase()];
            var n = code.charAt(1).toLowerCase() === 'x' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
            if (n < 0 || n > 1114111 || (n >= 55296 && n <= 57343)) return all;
            if (n <= 65535) return String.fromCharCode(n);
            n -= 65536; return String.fromCharCode(55296 + (n >> 10), 56320 + (n & 1023));
        }).trim();
}

function fqParagraphs(content) {
    var rows = [], expression = /<p\b[^>]*>([\s\S]*?)<\/p>/gi, match, remoteIndex = 0;
    while ((match = expression.exec(content)) !== null) {
        var text = fqParagraphText(match[1]);
        var identity = match[1].replace(/<\/?p\b[^>]*>/gi, '').trim();
        // XHTML chapter headings may themselves be wrapped in <p>. The official
        // paragraph endpoint counts body text, excluding this structural title.
        var heading = /^<h[1-6]\b[^>]*>[\s\S]*<\/h[1-6]\s*>$/i.test(identity);
        rows.push({index: rows.length, remoteIndex: text && !heading ? remoteIndex++ : null, html: match[1], text: text});
    }
    if (!rows.length) throw new Error('番茄：未能识别原始段落结构');
    return rows;
}

function fqOffset(value) {
    var n = Number(value);
    if (!isFinite(n) || n < 0 || Math.floor(n) !== n || n > 1000000) throw new Error('番茄：无效评论游标');
    return n;
}

function fqNormalizeParagraphComment(row, isReply) {
    var user = row.user_info || {}, pos = row.comment_pos || {};
    return {id: fqId(isReply ? row.reply_id : row.comment_id),
        name: fqString(user.user_name), content: fqString(row.text), avatar: fqReviewImage(user.user_avatar),
        authorBadge: user.is_author === true ? '作者' : '',
        likes: Number(row.digg_count) || 0, replies: Number(isReply ? row.reply_cnt : row.reply_count) || 0,
        time: Number(row.create_timestamp) || 0,
        paragraphStart: pos.start_para_index == null ? null : Number(pos.start_para_index),
        paragraphEnd: pos.end_para_index == null ? null : Number(pos.end_para_index),
        quote: fqString(row.para_src_content)};
}

function fqLoadParagraphStats(bookId, chapterId, host) {
    var json = fqHttpJson(fqEndpoint('comments')+'/reading/ugc/idea/list/v?aid=1967&book_id=' +
        fqId(bookId) + '&item_id=' + fqId(chapterId) + '&item_version=1', '段评统计', host);
    if (String(json.code) === '0' && json.data && json.data.idea_data === null) {
        return {counts: {}, version: fqString(json.data.newest_item_version) || '1', supported: false};
    }
    if (String(json.code) !== '0' || !json.data || !json.data.idea_data ||
        typeof json.data.idea_data !== 'object' || Array.isArray(json.data.idea_data)) {
        throw new Error('番茄：未取得段评统计');
    }
    var counts = {}, sourceCounts = json.data.idea_data;
    for (var key in sourceCounts) {
        if (Object.prototype.hasOwnProperty.call(sourceCounts, key) && /^\d+$/.test(key)) {
            var count = Number(sourceCounts[key].idea_count);
            if (isFinite(count) && count >= 0) counts[key] = count;
        }
    }
    return {counts: counts, version: fqString(json.data.newest_item_version) || '1', supported: true};
}

/* Compare the current paragraph with an exact, same-scope official anchor.
 * A stale hot-list quote is accepted only when current/old lists also share
 * a stable comment identity or observed paragraph hash. Never fuzzy-match text.
