function fqParagraphCheckRows(rows, bid, cid, index) {
    for (var i = 0; i < rows.length; i++) {
        var row = rows[i], pos = row && row.comment_pos || {};
        if (!row || String(row.book_id) !== bid || String(row.group_id) !== cid || Number(row.service_id) !== 1 ||
            pos.start_para_index == null || pos.end_para_index == null ||
