function fqParagraphData(bid, cid, version, index, start, sort, host) {
    var url = fqEndpoint('comments')+'/reading/ugc/idea/comment_list/v?aid=1967&book_id=' + bid +
        '&item_id=' + cid + '&para_index=' + index + '&count=20&offset=' + start + '&query_type=0&sort=' + sort +
