        row = hot[i];
        if (ids['id:' + fqId(row.comment_id)]) return {kind: 'comment', value: fqId(row.comment_id)};
    }
    for (i = 0; i < hot.length; i++) {
        hash = fqString(hot[i].novel_para_hash_code).toLowerCase();
