function fqLoadParagraphTopic(bookId, chapterId, commentId, offset, host) {
    var bid = fqId(bookId), cid = fqId(chapterId), rid = fqId(commentId), start = fqOffset(offset);
    var json = fqHttpJson(fqEndpoint('comments')+'/reading/ugc/reply/topic/v?aid=1967&book_id=' + bid +
        '&comment_id=' + rid + '&service_id=1&group_id=' + cid + '&count=20&offset=' + start, '段评回复', host);
    var data = json.data;
    if (String(json.code) !== '0' || !data || !data.comment || !Array.isArray(data.reply_list)) {
        throw new Error('番茄：未取得段评详情或回复');
    }
    if (String(data.comment.comment_id) !== rid || String(data.comment.group_id) !== cid ||
        String(data.comment.book_id) !== bid || Number(data.comment.service_id) !== 1) {
        throw new Error('番茄：段评归属不一致，已停止展示');
