// MD3 discovery helpers: select controls persist display values in infoMap and
// normalized request values in the source variable.
function qmExploreMapGet(map, key) {
    try {
        if (map && map.get) return map.get(key);
    } catch (e) {}
    try {
        if (map) return map[key];
    } catch (e) {}
    return '';
}

function qmExploreMapPut(map, key, value) {
    try {
        if (map && map.put) {
            map.put(key, value);
            return;
        }
    } catch (e) {}
    try {
        if (map && map.set) {
            map.set(key, value);
            return;
        }
    } catch (e) {}
    try {
        if (map) map[key] = value;
    } catch (e) {}
}

function qmExploreTrim(value) {
    return String(value == null ? '' : value).replace(/^\s+|\s+$/g, '');
}

function qmExploreValue(value, fallback) {
    return qmExploreTrim(value) === '' ? fallback : value;
}

function qmExploreRead(sourceValue) {
    var raw = '';
    try {
        raw = sourceValue && sourceValue.getVariable ? sourceValue.getVariable() : '';
    } catch (e) {}
    try {
        return JSON.parse(String(raw || '{}')) || {};
    } catch (e) {
        return {};
    }
}

function qmExploreWrite(sourceValue, value) {
    var serialized = JSON.stringify(value || {});
    try {
        if (sourceValue && sourceValue.putVariable) {
            sourceValue.putVariable(serialized);
            return true;
        }
    } catch (e) {}
    try {
        if (sourceValue && sourceValue.setVariable) {
            sourceValue.setVariable(serialized);
            return true;
        }
    } catch (e) {}
    return false;
}

function qmExploreOptionValue(value, options, fallback) {
    value = qmExploreTrim(value);
    for (var i = 0; i < options.length; i++) {
        if (String(options[i][0]) == value || String(options[i][1]) == value) return String(options[i][1]);
    }
    return String(fallback);
}

function qmExploreGroupNames(channel) {
    var groups = QM_TAGS[channel] || [];
    return groups.filter(function (group) {
        return qmExploreTagOptions(channel, group[0]).length > 0;
    }).map(function (group) { return String(group[0]); });
}

// Display names and tag_id values must come from the same validated catalog.
function qmExploreTagOptions(channel, groupName) {
    var groups = QM_TAGS[channel] || [];
    for (var i = 0; i < groups.length; i++) {
        if (String(groups[i][0]) != String(groupName)) continue;
        var options = [];
        String(groups[i][1]).split(',').forEach(function (item) {
            var pair = item.split(':');
            var name = qmExploreTrim(pair[0]);
            var id = qmExploreTrim(pair[1]);
            if (pair.length == 2 && name && /^[1-9][0-9]*$/.test(id)) {
                options.push({name: name, id: id});
            }
        });
        return options;
    }
    return [];
}

function qmExploreTagNames(channel, groupName) {
    return qmExploreTagOptions(channel, groupName).map(function (option) {
        return option.name;
    });
}

function qmExploreTagId(channel, groupName, tagName) {
    var option = qmExploreTagOption(channel, groupName, tagName);
    return option ? option.id : '';
}

function qmExploreTagOption(channel, groupName, tagName) {
    var options = qmExploreTagOptions(channel, groupName);
    for (var i = 0; i < options.length; i++) {
        if (options[i].name == String(tagName)) return options[i];
    }
    return options[0] || null;
}

function qmExploreGender(channel) {
    return ({'男频': 1, '女频': 2, '出版': 3})[channel] || 1;
}

function qmExploreNormalize(value) {
    value = value || {};
    var channel = qmExploreTrim(value.channel || value['频道'] || value.ch) || '男频';
    if (['男频', '女频', '出版'].indexOf(channel) < 0) channel = '男频';

    var groups = qmExploreGroupNames(channel);
    var group = qmExploreTrim(value.group || value['分类分组']);
    if (groups.indexOf(group) < 0) group = groups[0] || '';

    var option = qmExploreTagOption(channel, group, value.tag || value['分类标签']);
    if (!option) throw new Error('当前频道没有有效的分类标签，请更新书源');
    var tag = option.name;

    var over = qmExploreOptionValue(qmExploreValue(value.over, value['状态']), [['全部状态', '-99'], ['完结', '1'], ['连载', '0']], '-99');
    var words = qmExploreOptionValue(qmExploreValue(value.words, value['字数']), [['全部字数', '-99'], ['50万以下', '1'], ['50-100万', '2'], ['100-300万', '3'], ['300万以上', '4']], '-99');
    var sort = qmExploreOptionValue(qmExploreValue(value.sort, value['排序']), [['按热度', '0'], ['按更新', '1'], ['按评分', '2'], ['按新书', '3']], '0');

    return {channel: channel, group: group, tag: tag, over: over, words: words, sort: sort};
}

function qmExploreStateFromInfo(infoMapValue, sourceValue) {
    var stored = qmExploreNormalize(qmExploreRead(sourceValue));
    var value = {
        channel: qmExploreValue(qmExploreMapGet(infoMapValue, '频道'), stored.channel),
        group: qmExploreValue(qmExploreMapGet(infoMapValue, '分类分组'), stored.group),
        tag: qmExploreValue(qmExploreMapGet(infoMapValue, '分类标签'), stored.tag),
        over: qmExploreValue(qmExploreMapGet(infoMapValue, '状态'), stored.over),
        words: qmExploreValue(qmExploreMapGet(infoMapValue, '字数'), stored.words),
        sort: qmExploreValue(qmExploreMapGet(infoMapValue, '排序'), stored.sort)
    };
    return qmExploreNormalize(value);
}

function qmSaveExploreState(infoMapValue, sourceValue) {
    var value = qmExploreStateFromInfo(infoMapValue, sourceValue);
    qmExploreMapPut(infoMapValue, '频道', value.channel);
    qmExploreMapPut(infoMapValue, '分类分组', value.group);
    qmExploreMapPut(infoMapValue, '分类标签', value.tag);
    qmExploreMapPut(infoMapValue, '状态', value.over == '-99' ? '全部状态' : (value.over == '1' ? '完结' : '连载'));
    qmExploreMapPut(infoMapValue, '字数', value.words == '-99' ? '全部字数' : ({'1': '50万以下', '2': '50-100万', '3': '100-300万', '4': '300万以上'}[value.words] || '全部字数'));
    qmExploreMapPut(infoMapValue, '排序', value.sort == '0' ? '按热度' : (value.sort == '1' ? '按更新' : (value.sort == '2' ? '按评分' : '按新书')));
    try {
        if (infoMapValue && infoMapValue.saveNow) infoMapValue.saveNow();
    } catch (e) {}
    qmExploreWrite(sourceValue, value);
    return value;
}

function qmBuildExploreUrlFromEncoded(javaValue, encoded, page, sourceValue) {
    var value;
    try {
        value = JSON.parse(decodeURIComponent(String(encoded || '')));
    } catch (e) {
        value = {};
    }
    value = qmExploreNormalize(value);
    if (sourceValue) qmExploreWrite(sourceValue, value);
    var tag = qmExploreTagOption(value.channel, value.group, value.tag);
    var params = {
        gender: qmExploreGender(value.channel),
        tag_id: tag.id,
        over: value.over,
        words: value.words,
        sort: value.sort
    };
    return qmTag(params.gender, params.tag_id, page, params.over, params.words, params.sort);
