@js:
if (QMA.meta.call(this,baseUrl,result)) { QMA.content.call(this,baseUrl,result); } else {
var seg = String(java.hexDecodeToString(result)).split('/');
var bid = String(java.get('bid'));
var story = seg[2] == '1';
var out, valid = false, res;
try {
    res = JSON.parse(java.ajax(qmContent(bid, seg[0], story)));
    if (!(res.data && res.data.content)) res = JSON.parse(java.ajax(qmContent(bid, seg[0], !story)));
    if (res.data && res.data.content) {
        out = qmDecode(res.data.content);
        valid = true;
    } else out = '七猫服务器未返回本章正文：' + (res.errors ? res.errors.details : '未知错误');
} catch (e) { out = '正文获取失败：' + e; }
if (valid) out = qmpcAnnotate.call(this, out, bid, seg[0], String(res.data.content_md5 || seg[1] || ''));
out;

}

