    resp.body.comments.forEach(comment => {
        if (comment.userId === uid && comment.comment === commentText) list.push(comment.id)

        if (comment.hasReplies === true) {
            let resp = getAjaxJson(urlNovelCommentsReply(comment.id, 1), true)
