    if (settingName === "DEFAULT") {
        try { java.reLoginView() } catch (e) {}
        try { source.refreshExplore() } catch (e) {}
        try { java.refreshBookInfo() } catch(e) {}
        try { java.refreshBookToc() } catch(e) {}
