function formatDateText(text) {
  const match = text.match(/^(\\d+)\\s*天前发布$/);
  if (!match) return text;
  const daysAgo = Number(match[1]);
  if (daysAgo <= 3) return text;
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return \`$\{y}-$\{m}-$\{d} [$\{daysAgo}天前]\`;
}

function parseContent(content,emo,atname,jump_url){
     if(emo){
         let emok = Object.keys(emo);

         let emok2 = emok.map(k =>
             k.replace(/[.*+?^$\{}()|[\\]\\\\]/g, m => '\\\\' + m)
          );

         emok2.forEach((x,i)=>{
             let re = new RegExp(x,'g');
            content = content.replace(re,"<img src=\\""+emo[emok[i]].url+"\\" class=\\"ef\\">")
         })
      }

      if(atname){
          let atnamek = Object.keys(atname);
          let atname2 = atnamek.map(k => 
                   k.replace(/[.*+?^$\{}()|[\\]\\\\]/g, m => '\\\\' + m)
         );

         atname2.forEach((x,i)=>{
             let re = new RegExp("@"+x,'g');
            content = content.replace(re,"<span class=\\"atname\\" data-id=\\""+atname[atnamek[i]]+"\\">@"+atnamek[i]+"</span>")
         })
      }

      if(jump_url){
          let jump_urlk = Object.keys(jump_url);
          let jump_url2 = jump_urlk.map(k=> 
                   k.replace(/[.*+?^$\{}()|[\\]\\\\]/g, m => '\\\\' + m)
         );

         jump_url2.forEach((x,i)=>{
             let re = new RegExp(x,'g');
             let aid =/^\\d+$/.test(jump_url[jump_urlk[i]].click_report)?jump_url[jump_urlk[i]].click_report:jump_urlk[i];

             let type = /^\\d+$/.test(aid)?"🎥":(/^http/.test(aid)?"🔗":"🔎");
            content = content.replace(re,"<span class=\\"jump_url\\" data-aid=\\""+aid+"\\">"+type+jump_url[jump_urlk[i]].title+"</span>")
         })
