  var hue = String(book.dominant_hue || d.dominant_hue || '#e67e22');
  if (hue.charAt(0) !== '#') hue = '#' + hue;
  if (hue.length === 4) hue = '#' + hue[1] + hue[1] + hue[2] + hue[2] + hue[3] + hue[3];
