  var rl = u.role != null ? u.role : item.role;
  var ia = String(u.is_author != null ? u.is_author : (item.is_author != null ? item.is_author : '0')) == '1' || String(rl || '') == '1';
  var ab = String(u.avatar_box || item.avatar_box || '');
  var nc = String(u.nickname_color || item.nickname_color || '');
  var pics = [],
    emo = '';
  var pi2 = item.pic_info || {};
