  if (pu2) {
    if (String(pi2.pic_type || '') == '2') emo = pu2;
    else pics.push(pu2)
  }
  var rp = item.image_list || item.pic_list || item.comment_pic || [];
  if (!Array.isArray(rp)) rp = rp ? [rp] : [];
  rp.forEach(function(x) {
    var url = typeof x == 'string' ? x : (x.url_orig || x.url || x.image_link);
    if (!url) return;
    if (typeof x != 'string' && String(x.pic_type || '') == '2' && !emo) emo = String(url);
    else pics.push(String(url))
  });
  var rv = item.reply_count != null ? item.reply_count : item.sub_comment_count;
  var re = rv == null ? 0 : Number(rv || 0);
