    ip: String(item.ip || ''),
    tags: tg,
    likes: Number(item.like_count || 0),
    replies: re,
    pics: pics,
    emoji: emo,
    hot: !!hot,
    god: String(item.is_god || item.god_flag || '0') == '1',
    levelIcon: li,
    level: String(lv || ''),
    medalIcon: String(m.icon_url || ''),
    medalTitle: String(m.alias_name || ''),
    badgeIcon: bgi,
    badgeTitle: String(bi.badge || item.badge || ''),
    badgeLevel: String(cl || ''),
    badgeColor: String(bi.center_color || bi.start_color || ''),
    honorIcon: String(hi.bg_url || ''),
    honorTitle: String(hi.tag_title || ''),
    honorColor: String(hi.tag_color || ''),
    honorType: String(hi.type || ''),
    isAuthor: ia,
    authorLevel: String(al || ''),
    role: String(rl == null ? '' : rl),
    nicknameColor: nc,
