function jjShelfGroups() {
    var E = dpEnv(this);
    var java = E.java, cache = _jjCache.call(this);
    var now = Date.now();
    var token = _jjToken.call(this);
    // v5.90：停用分组缓存——每次刷新发现页都实时拉取账号分组，彻底解决
    // 「书架分类与账号不同步」（5.88/5.89 用户反馈；缓存写入保留仅作调试，读取路径已移除）。
    if (!java) { return []; }
    if (!token) {
        try { java.toast('书架分组：未登录晋江账号，请先登录'); } catch (_e) {}
        return [];
    }
    var cipherBody = '';
    var encErr = '';
    try {
        cipherBody = String(encode.call(this, '{\"versionCode\":\"507\",\"token\":\"' + String(token).replace(/\\"/g, '\\\\"') + '\"}'));
    } catch (eE) { encErr = String(eE); }
    if (cache) {
        try {
            cache.put('jjDbg_cipher', cipherBody ? cipherBody.slice(0, 400) : '');
            cache.put('jjDbg_encErr', encErr.slice(0, 400));
            cache.put('jjDbg_tokenLen', String(token.length));
            cache.put('jjDbg_tokenHead', String(token).slice(0, 16));
        } catch (eD) {}
    }
    if (!cipherBody) { return []; }

    var FC_URL = 'https://android.jjwxc.com/app.jjwxc/android/reading/FavoriteClass/favoriteClass';
    // v5.87 关键修复：必须显式 Content-Type: application/octet-stream，
    // 否则 Legado 把字符串 body 当表单编码，base64 密文中 / = + 被转义，服务端无法解密 -> 1004。
    // 与 loginUrl 扫码换 token 的成功路径一致（该路径本就显式设置 octet-stream）。
    var FC_HDRS = {
        'User-Agent': 'okhttp/4.9.0', 'source': 'android',
        'versiontype': 'reading', 'versioncode': '507',
        'version-code': '507', 'referer': 'https://android.jjwxc.net/?v=507',
        'Content-Type': 'application/octet-stream'
    };

    function tryWrite(resp, label) {
        if (!cache) { return; }
        try {
            var key = 'jjDbg_' + label;
            cache.put(key + 'Len', String(resp.length));
            cache.put(key + 'Head', resp.slice(0, 400));
            cache.put(key + 'Tail', resp.slice(-200));
        } catch (e) {}
    }

    var resp = '';
    var tried = '';
    var methodErr = '';

    // 尝试 1：java.ajax（本书源其他 POST 均走此路径）
    try {
        tried += 'ajax;';
        var optsFc = JSON.stringify({
            method: 'POST', body: cipherBody,
            headers: {
                'User-Agent': 'okhttp/4.9.0', 'source': 'android',
                'versiontype': 'reading', 'versioncode': '507',
                'version-code': '507', 'referer': 'https://android.jjwxc.net/?v=507',
                'Content-Type': 'application/octet-stream'
            }
        });
        resp = String(java.ajax(FC_URL + ',' + optsFc));
        tryWrite(resp, 'ajax');
        if (resp && resp.indexOf('"code":"200"') >= 0) { cache.put('jjDbg_method', 'ajax'); }
    } catch (eA) {
        methodErr += 'ajaxErr=' + String(eA).slice(0, 200) + ';';
        try { cache.put('jjDbg_ajaxErr', String(eA).slice(0, 400)); } catch (_e) {}
    }

    // 尝试 2：java.connect（可拿到完整响应对象）
    if (!resp || resp.indexOf('"code":"200"') < 0) {
        try {
            tried += 'connect;';
            var optsConn = JSON.stringify({
                method: 'POST', body: cipherBody,
                headers: {
                    'User-Agent': 'okhttp/4.9.0', 'source': 'android',
                    'versiontype': 'reading', 'versioncode': '507',
                    'version-code': '507', 'referer': 'https://android.jjwxc.net/?v=507',
                    'Content-Type': 'application/octet-stream'
                }
            });
            var rConn = java.connect(FC_URL + ',' + optsConn);
            resp = String(rConn.body ? rConn.body() : (rConn.bodyAsString ? rConn.bodyAsString() : rConn));
            tryWrite(resp, 'connect');
            if (resp && resp.indexOf('"code":"200"') >= 0) { cache.put('jjDbg_method', 'connect'); }
        } catch (eC2) {
            methodErr += 'connectErr=' + String(eC2).slice(0, 200) + ';';
            try { cache.put('jjDbg_connectErr', String(eC2).slice(0, 400)); } catch (_e) {}
        }
    }

    if (cache) {
        try {
            cache.put('jjDbg_tried', tried);
            cache.put('jjDbg_methodErr', methodErr.slice(0, 400));
            cache.put('jjDbg_finalResp', resp ? resp.slice(0, 400) : '');
            var mc = resp.match(/"code"\s*:\s*"([^"]*)"/);
            cache.put('jjDbg_code', mc ? ('"'+mc[1]+'"') : 'none');
        } catch (eD2) {}
    }

    // 1004 = 登录态失效，明确提示用户
    if (resp && resp.indexOf('"code":"1004"') >= 0) {
        try { java.toast('书架分类：晋江登录状态已过期，请重新登录书源'); } catch (_e) {}
        return [];
    }
    if (!resp || resp.indexOf('"code":"200"') < 0) { return []; }

    var groups = [];
    var seen = {};
    try {
        var root = JSON.parse(resp);
        var arr = (root && root.data && root.data.length) ? root.data : [];
        for (var i = 0; i < arr.length; i++) {
            var it = arr[i];
            if (!it) { continue; }
            var gid = String(it.classid);
            var gname = String(it.classname || '');
            if (!gid || !gname || seen[gid]) { continue; }
            seen[gid] = true;
            groups.push({ id: gid, name: gname });
        }
    } catch (eP) { return []; }
    if (cache) {
        try {
            cache.put('jjShelfGroups', JSON.stringify(groups));
            cache.put('jjShelfGroupsTs', String(now));
            cache.put('jjShelfGroupsToken', String(token || ''));
        } catch (eS) {}
    }
    return groups;
}

