/* 晋江登录协议实测（2026-08-27 真机接口验证）：
 * 1. 无验证码登录 -> 服务端风控返回 6018「请校验验证码~」或 221003（设备验证）
 * 2. 解决方式：登录请求追加 checktype=phone|email & checkdevicecode=<任意非空值> 即可放行
 *    （实测假码 000000 通过；若用户收到真实验证码则优先使用真码）
 * 3. getDeviceSecurityCode 验证码下发接口对无App签名请求一律拒绝（2021/1004），书源内走不通
 * 4. legado JS 无全局 Map() 函数，读取登录头须用 source.getLoginHeaderMap().get(key)
 */
function guessCheckType(account){
	return /@/.test(String(account)) ? "email" : "phone";
}
function doLoginOnce(account, password, checktype, code){
	var en = jjEncode(password);
	var now = String(Date.now());
	var id = ("846"+now+"4893")+":"+java.androidId()+"d4:";
	var sign = jjEncode(now+"_"+id+"_");
	var url = "https://app.jjwxc.org/androidapi/login?versionCode=401"
		+"&loginName="+encodeURIComponent(account)
		+"&encode=1"
		+"&loginPassword="+encodeURIComponent(en)
		+"&sign="+encodeURIComponent(sign)
		+"&identifiers="+encodeURIComponent(id)
		+"&autologin=1";
	if(checktype && code){
		url += "&checktype="+checktype+"&checkdevicecode="+encodeURIComponent(code);
	}
	var r = String(java.ajax(url));
	try{
		return JSON.parse(r);
	}catch(e){
		return {"code":"-1","message":r.slice(0,120)};
	}
}
function saveLoginOk(d, extra){
	jjSetHeaders("token="+d.token);
	// v5.102: 登录成功后同步书架分组
	try { var _c=cache; try{_c.delete("jjShelfGroups");}catch(e){} try{_c.delete("jjShelfGroupsTs");}catch(e){} try{_c.delete("jjShelfGroupsToken");}catch(e){} try{java.refreshExplore();}catch(e){} } catch(e){}
	var welcome = "登录成功："+(d.nickName||d.readerId||"")+"\n余额："+(d.balance||"?")+" 晋江币";
	if(d.readergrade){ welcome += "\n等级："+d.readergrade; }
	if(extra){ welcome += "\n"+extra; }
	welcome += "\n请刷新目录后阅读VIP章节";
	java.longToast(welcome);
}
function loginByPassword(){
	try{
		var account = String(result.get("账号")||"").replace(/\s/g,"");
		var password = String(result.get("密码")||"");
		if(!account || !password){
			java.longToast("请先填写账号和密码");
			return;
		}
		var code = String(result.get("验证码（可留空，6018时自动过验证）")||"").replace(/\s/g,"");
		var ct = guessCheckType(account);
		// 第一次尝试：用户已填验证码则直接带上；否则裸登录
		var d;
		if(code){
			d = doLoginOnce(account, password, ct, code);
		}else{
			d = doLoginOnce(account, password, null, null);
		}
		if(d.token && /^\d+_\w{16,}/.test(String(d.token))){
			saveLoginOk(d, "");
			return;
		}
		var c = String(d.code||"");
		// 6018/221003：服务端要求设备验证码 -> 自动带 checktype+checkdevicecode 重试
		// （实测 checkdevicecode 任意非空值即可放行；优先用用户填的真实验证码）
		if(c=="6018" || c=="221003" || /请校验验证码/.test(String(d.message||""))){
			var useCode = code || "000000";
			var d2 = doLoginOnce(account, password, ct, useCode);
			if(d2.token && /^\d+_\w{16,}/.test(String(d2.token))){
				saveLoginOk(d2, "（已自动通过设备验证）");
				return;
			}
			var c2 = String(d2.code||"");
			if(c2=="6018" || c2=="221003" || /请校验验证码/.test(String(d2.message||""))){
				// 换一种 checktype 再试（email 账号用 phone 反之亦然）
				var ct2 = (ct=="phone") ? "email" : "phone";
				var d3 = doLoginOnce(account, password, ct2, useCode);
				if(d3.token && /^\d+_\w{16,}/.test(String(d3.token))){
					saveLoginOk(d3, "（已自动通过设备验证-"+ct2+"）");
					return;
				}
				java.longToast("自动验证未通过："+(d3.message||JSON.stringify(d3).slice(0,120))
					+"\n请尝试：①检查账号密码 ②点【扫码登录】");
				return;
			}
			java.longToast("登录失败："+(d2.message||JSON.stringify(d2).slice(0,120)));
			return;
		}
		if(c=="1004" || /登入验证失败/.test(String(d.message||""))){
			java.longToast("登录失败：账号或密码错误（1004）");
			return;
		}
		java.longToast("登录失败："+(d.message||JSON.stringify(d).slice(0,150)));
	}catch(e){
		java.log(e);
		java.toast("账密登录失败："+e);
	}
}
