        var o = {};
        try { o = JSON.parse(String(source.getVariable() || '{}')); } catch(e){}
        o['段评设置'] = d;
        source.setVariable(JSON.stringify(o));
    } catch(e){}
    try {
        cookie.setCookie("https://m.jjwxc.net/", "dpsettings=" + encodeURIComponent(JSON.stringify(d)));
